@@ -1,0 +1,18 @@
+namespace CheckoutPricing.Domain;
+
+public static class PromoCodePolicy
+{
+    private const int Welcome5Cents = 500;
+    private const int Summer10CapCents = 1_500;
+
+    public static int For(string? code, int amountAfterLoyaltyCents)
+    {
+        if (string.Equals(code, "WELCOME5", StringComparison.OrdinalIgnoreCase))
+            return Welcome5Cents;
+
+        if (string.Equals(code, "SUMMER10", StringComparison.OrdinalIgnoreCase))
+            return Math.Min(amountAfterLoyaltyCents / 10, Summer10CapCents);
+
+        return 0;
+    }
+}

diff --git a/tmp/vally-eval-trial-saCBHM/src/CheckoutPricing.Domain/DiscountPolicy.cs b/tmp/vally-eval-trial-saCBHM/src/CheckoutPricing.Domain/DiscountPolicy.cs
