 public sealed class QuoteCheckout
 {
-    public CheckoutQuote Handle(QuoteCheckoutQuery query) => new(0, 0, 0);
+    public CheckoutQuote Handle(QuoteCheckoutQuery query)
+    {
+        var payableCents = query.SubtotalCents - DiscountPolicy.For(query.SubtotalCents, query.LoyaltyTier, query.PromoCode);
+        var shippingCents = query.Express
+            ? ShippingFeePolicy.Express(query.LoyaltyTier)
+            : ShippingFeePolicy.Standard(payableCents, query.LoyaltyTier);
+        return new(payableCents, shippingCents, payableCents + shippingCents);
+    }
 }
